  const [formTab, setFormTab] = useState("Details");
  const [formNameDraft, setFormNameDraft] = useState("");
  const [formCampaignDraft, setFormCampaignDraft] = useState("");
  const [formSyncEnabled, setFormSyncEnabled] = useState(false);
  const [formAllocationEnabled, setFormAllocationEnabled] = useState(true);
  const [addEventOpen, setAddEventOpen] = useState(false);
