  const [accounts, setAccounts] = useState([
    { id: "meta-business-1", name: "iFranchise Business", accountId: "123456789012345", connectedOn: "Oct 12, 2026, 11:20 AM", lastSync: "Today, 11:24 AM", primary: true },
    { id: "meta-business-2", name: "iFranchise Ads", accountId: "987654321098765", connectedOn: "Oct 10, 2026, 09:16 AM", lastSync: "Today, 10:02 AM", primary: false },
  ]);
  const [accountMenuId, setAccountMenuId] = useState<string | null>(null);
