  const [editingAccountId, setEditingAccountId] = useState<string | null>(null);
  const [accountNameDraft, setAccountNameDraft] = useState("");
  const [addAccountStep, setAddAccountStep] = useState(0);
  const [selectedBusinessAccounts, setSelectedBusinessAccounts] = useState<string[]>([]);
  const [businessAccountQuery, setBusinessAccountQuery] = useState("");
  const sections = ["Accounts", "Assets", "Events (CAPI)", "Sync settings", "Field mapping", "Access & permissions"];
  const formRows = forms.map((id, index) => ({ id, name: formOverrides[id]?.name ?? id, platform: index % 2 === 0 ? "Instagram" : "Facebook", campaign: formOverrides[id]?.campaign ?? (["Odette Franchise · IG", "Emori · FB", "Brand Awareness", "Investor · IG"][index] ?? "Meta Lead Ads"), leads: [84, 52, 18, 9][index] ?? 0, lastSync: index < 2 ? "Today, 11:24 AM" : "Oct 28, 04:10 PM", active: index < 2 }));
  const visibleForms = formRows.filter(form => `${form.name} ${form.campaign} ${form.platform}`.toLowerCase().includes(formQuery.toLowerCase()) && (formPlatform === "All platforms" || form.platform === formPlatform) && (formCampaign === "All campaigns" || form.campaign === formCampaign) && (formStatus === "All statuses" || (form.active && selectedForms.includes(form.name) ? "Active" : "Inactive") === formStatus));
  const selectedManagedForm = formRows.find(form => form.id === managedForm);
  function openManagedForm(form: (typeof formRows)[number]) { setManagedForm(form.id); setFormNameDraft(form.name); setFormCampaignDraft(form.campaign); setFormSyncEnabled(selectedForms.includes(form.name)); setFormAllocationEnabled(true); setFormTab("Details"); }
  function saveManagedForm() {
    if (!managedForm) return;
    const previousName = formRows.find(form => form.id === managedForm)?.name ?? managedForm;
    const updated = formNameDraft.trim() || previousName;
    setFormOverrides(current => ({ ...current, [managedForm]: { name: updated, campaign: formCampaignDraft }, [updated]: { name: updated, campaign: formCampaignDraft } }));
    setSelectedForms(current => current.map(name => name === previousName ? updated : name));
    onUpdateForm(previousName, updated, formCampaignDraft);
    setManagedForm(updated);
    onNotify(`${updated} settings updated in this preview.`);
  }
  function startAddEvent() { setEditingEventId(null); setEventCrmDraft("Opportunity Created"); setEventMetaDraft("InitiateCheckout"); setEventTriggerDraft("When an opportunity is created"); setEventDedupDraft(true); setAddEventOpen(true); }
  function editEvent(event: (typeof eventMappings)[number]) { setEditingEventId(event.id); setEventCrmDraft(event.crm); setEventMetaDraft(event.meta); setEventTriggerDraft(event.trigger); setEventDedupDraft(event.dedup); setAddEventOpen(true); }
  function saveEventMapping() {
    if (editingEventId) setEventMappings(current => current.map(event => event.id === editingEventId ? { ...event, crm: eventCrmDraft, meta: eventMetaDraft, trigger: eventTriggerDraft, dedup: eventDedupDraft } : event));
    else setEventMappings(current => [...current, { id: `event-${Date.now()}`, crm: eventCrmDraft, meta: eventMetaDraft, trigger: eventTriggerDraft, dedup: eventDedupDraft, priority: "Medium", active: true }]);
    setAddEventOpen(false);
    onNotify(`The ${eventCrmDraft} mapping was ${editingEventId ? "updated" : "added"} in this preview.`);
  }
  function saveMember() {
    const email = memberEmail.trim().toLowerCase();
    if (!email || !email.includes("@")) { onNotify("Enter a valid team member email address."); return; }
    const existing = members.find(member => member.id === editingMemberId);
    const name = email.split("@")[0].split(/[._-]/).map(part => part.charAt(0).toUpperCase() + part.slice(1)).join(" ");
    if (existing) setMembers(current => current.map(member => member.id === editingMemberId ? { ...member, name, email, role: memberRole, permissions: memberPermissions } : member));
    else setMembers(current => [...current, { id: `member-${Date.now()}`, name, email, role: memberRole, permissions: memberPermissions, status: "Active" }]);
    setShowMemberForm(false); setEditingMemberId(null); setMemberEmail(""); setMemberRole("Manager"); setMemberPermissions(["View Integration Details", "Manage Configuration", "Manage Assets"]);
    onNotify(`Team access ${existing ? "updated" : "added"} in this preview.`);
  }
