    setAssets(current => [...current, ...selected.filter(asset => !current.some(item => item.id === asset.id)).map(asset => ({ ...asset, account: businessAccount, permissions: asset.type === "Facebook Pages" ? reviewAssetPermissions : reviewAssetPermissions.filter(permission => permission !== "Lead Forms"), status: "Connected", lastSync: "Just now" }))]);
    setAssetAddStep(0);
