function GoogleAdsBrandLogo() { return <svg className="mk-logo-google" viewBox="0 0 48 48" role="img" aria-label="Google Ads"><path d="M10 37 24 11" fill="none" stroke="#FBBC04" strokeLinecap="round" strokeWidth="9"/><path d="m24 11 15 26" fill="none" stroke="#4285F4" strokeLinecap="round" strokeWidth="9"/><circle cx="10" cy="37" r="5" fill="#34A853"/></svg>; }
